package com.starhub;
import static org.junit.jupiter.api.Assertions.*;
import static org.mockito.Mockito.*;
import jakarta.servlet.*;import jakarta.servlet.http.*;import java.io.*;import java.util.*;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class AtomicEarlyAdmissionTest {
 record Response(HttpServletResponse http,ByteArrayOutputStream bytes){}
 Response response()throws Exception {var r=mock(HttpServletResponse.class);var bytes=new ByteArrayOutputStream();when(r.getOutputStream()).thenReturn(new ServletOutputStream(){public void write(int b){bytes.write(b);}public boolean isReady(){return true;}public void setWriteListener(WriteListener l){throw new UnsupportedOperationException();}});doAnswer(i->{bytes.reset();return null;}).when(r).resetBuffer();return new Response(r,bytes);}
 HttpServletRequest request(String method,String action)throws Exception {var r=mock(HttpServletRequest.class);when(r.getMethod()).thenReturn(method);when(r.getServletPath()).thenReturn(method.equals("GET")?"/api/account":"/api/workspace");when(r.getContentType()).thenReturn("application/json");when(r.getHeader("X-Starhub-Client")).thenReturn("web");when(r.getHeader("Origin")).thenReturn("https://starhub.zhongjiehuang.com");var bytes=new ByteArrayInputStream(("{\"action\":\""+action+"\",\"operationId\":\""+UUID.randomUUID()+"\"}").getBytes(java.nio.charset.StandardCharsets.UTF_8));when(r.getInputStream()).thenReturn(new ServletInputStream(){public int read(){return bytes.read();}public int read(byte[] b,int o,int n){return bytes.read(b,o,n);}public boolean isFinished(){return bytes.available()==0;}public boolean isReady(){return true;}public void setReadListener(ReadListener l){throw new UnsupportedOperationException();}});return r;}
 @Test void definiteMemoryRejectionDoesNotProbeOrReachSqlAndReturnsNotStarted()throws Exception {var calls=new AtomicInteger();var lease=ProviderAdmission.tryEnter();assertNotNull(lease);try{var result=response();AtomicHttp.run(request("POST","listChats"),result.http,(a,b)->fail("No chain"),null,new Properties(),()->{calls.incrementAndGet();throw StorageFailure.unavailable();},(a,b)->fail("No SQL"));verify(result.http).setStatus(429);assertEquals(0,calls.get());assertEquals("NOT_STARTED",ModelGateway.JSON.readTree(result.bytes.toByteArray()).path("operationState").asText());}finally{lease.close();}}
 @Test void acceptedReadWriteGetAndSegmentedPathsCheckReadinessBeforeAnySqlAndReleaseMemory()throws Exception {for(String[] value:new String[][]{{"POST","listChats"},{"POST","saveChat"},{"POST","upload"},{"POST","deleteFile"},{"POST","cancelUpload"},{"GET",""}}){var calls=new AtomicInteger();var result=response();AtomicHttp.run(request(value[0],value[1]),result.http,(a,b)->fail("No chain before readiness"),null,new Properties(),()->{calls.incrementAndGet();throw StorageFailure.unavailable();},(a,b)->fail("No SQL before readiness"));assertEquals(1,calls.get(),Arrays.toString(value));verify(result.http).setStatus(503);var next=ProviderAdmission.tryEnter();assertNotNull(next,"Admission permit leaked");next.close();}}
}
